#!/usr/bin/env python3
import pathlib,hashlib,base64,gzip,json,fcntl,tempfile,shutil,os,sys,runpy
PAYLOAD_SHA='d8ee006073f23292089bf67736548b4e2800972b5380cfea98f390f870f47fd0'
PAYLOAD=''
base=pathlib.Path.home()/"paper3-r1-repairs"
root=base/PAYLOAD_SHA[:20]
base.mkdir(parents=True,exist_ok=True)
with (base/"install.lock").open("a") as lock:
 fcntl.flock(lock,fcntl.LOCK_EX)
 raw=gzip.decompress(base64.b64decode(PAYLOAD))
 if hashlib.sha256(raw).hexdigest()!=PAYLOAD_SHA:raise SystemExit("REPAIR_PACKAGE_HASH_MISMATCH")
 files=json.loads(raw)
 valid=root.is_dir() and all((root/n).is_file() and hashlib.sha256((root/n).read_bytes()).hexdigest()==hashlib.sha256(v.encode()).hexdigest() for n,v in files.items())
 if not valid:
  stage=pathlib.Path(tempfile.mkdtemp(prefix=".install-",dir=base))
  try:
   for name,value in files.items():(stage/name).write_text(value)
   if root.exists():
    for name in files:os.replace(stage/name,root/name)
   else:os.rename(stage,root)
  finally:
   if stage.exists():shutil.rmtree(stage)
print(json.dumps({"event":"R1_REPAIR_PACKAGE_VERIFIED","package":str(root),"payload_sha256":PAYLOAD_SHA}),flush=True)
sys.path.insert(0,str(root))
runpy.run_path(str(root/"apply_fix.py"),run_name="__main__")
